import { createHash, randomUUID } from "node:crypto";
import type { CalendarAdapter, CrmAdapter, CrmRecord, WorkflowStorage, WorkflowTransaction } from "./ports.js";
import type { CalendarChange } from "./ports.js";
import type { SyncConflict, SyncCursor } from "./schema.js";

const hash = (value: unknown) => createHash("sha256").update(JSON.stringify(value)).digest("hex");
export interface InboundSyncResult { ignored: number; conflicts: number; cursor?: string; }

export class InboundSyncService {
  constructor(private readonly storage: WorkflowStorage, private readonly now: () => Date = () => new Date()) {}

  async pullCalendar(input: { organizationId: string; provider: "google" | "outlook"; connectionId: string; adapter: CalendarAdapter; windowStart?: string; windowEnd?: string }): Promise<InboundSyncResult> {
    const cursorRecord = await this.getCursor(input.organizationId, input.provider, input.connectionId);
    const pulled = await input.adapter.listChanges({ connectionId: input.connectionId, cursor: cursorRecord?.cursor, windowStart: input.windowStart, windowEnd: input.windowEnd });
    let ignored = 0;
    let conflicts = 0;
    for (const change of pulled.changes) {
      const result = await this.stageCalendarChange(input.organizationId, input.provider, change);
      if (result === "ignored") ignored += 1; else conflicts += 1;
    }
    await this.saveCursor(input.organizationId, input.provider, input.connectionId, pulled.cursor);
    return { ignored, conflicts, cursor: pulled.cursor };
  }

  async pullCrm(input: { organizationId: string; provider: string; connectionId: string; adapter: CrmAdapter }): Promise<InboundSyncResult> {
    const cursorRecord = await this.getCursor(input.organizationId, input.provider, input.connectionId);
    const pulled = await input.adapter.pullChanges(cursorRecord?.cursor);
    let ignored = 0;
    let conflicts = 0;
    for (const record of pulled.records) {
      const result = await this.stageCrmRecord(input.organizationId, input.provider, record);
      if (result === "ignored") ignored += 1; else conflicts += 1;
    }
    await this.saveCursor(input.organizationId, input.provider, input.connectionId, pulled.cursor);
    return { ignored, conflicts, cursor: pulled.cursor };
  }

  private async stageCalendarChange(organizationId: string, provider: "google" | "outlook", change: CalendarChange): Promise<"ignored" | "conflict"> {
    return this.storage.transact(organizationId, async (tx) => {
      const link = (await tx.list("calendarEvent", (item) => item.provider === provider && item.externalId === change.externalId))[0];
      if (!link) {
        await this.createConflict(tx, organizationId, { kind: "calendar", provider, externalId: change.externalId, reason: "unlinked_external", externalVersion: change.etag, externalPayload: change.payload as unknown as Record<string, unknown> | undefined });
        return "conflict";
      }
      const call = await tx.get("call", link.callId);
      if (!call) {
        await this.createConflict(tx, organizationId, { kind: "calendar", provider, aggregateId: link.callId, externalId: change.externalId, reason: "version_mismatch", externalVersion: change.etag, externalPayload: change.payload as unknown as Record<string, unknown> | undefined });
        return "conflict";
      }
      if (change.deleted) {
        await tx.update("calendarEvent", { ...link, deletedExternallyAt: this.now().toISOString(), updatedAt: this.now().toISOString() }, link.version);
        await this.createConflict(tx, organizationId, { kind: "calendar", provider, aggregateId: call.id, externalId: change.externalId, reason: "external_deleted", localVersion: call.version, externalVersion: change.etag, localPayload: this.localCalendarPayload(call), externalPayload: change.payload as unknown as Record<string, unknown> | undefined });
        return "conflict";
      }
      const sameRevision = change.payload?.originId === call.id && change.payload.syncRevision === link.syncRevision;
      const samePayload = change.payload ? hash(change.payload) === link.contentHash : false;
      if (change.etag === link.etag || sameRevision && samePayload) return "ignored";
      await this.createConflict(tx, organizationId, { kind: "calendar", provider, aggregateId: call.id, externalId: change.externalId, reason: "external_changed", localVersion: call.version, externalVersion: change.etag, localPayload: this.localCalendarPayload(call), externalPayload: change.payload as unknown as Record<string, unknown> | undefined });
      return "conflict";
    });
  }

  private localCalendarPayload(call: { id: string; purpose: string; schedule: { startsAt: string; durationMinutes: number; timezone: string; location?: string; remindersMinutes: number[]; recurrenceRule?: string }; version: number }): Record<string, unknown> {
    return { purpose: call.purpose, ...call.schedule, originId: call.id, syncRevision: call.version };
  }

  private async stageCrmRecord(organizationId: string, provider: string, record: CrmRecord): Promise<"ignored" | "conflict"> {
    return this.storage.transact(organizationId, async (tx) => {
      const local = record.object === "account"
        ? (await tx.list("account", (item) => item.externalId === record.externalId))[0]
        : record.object === "contact"
          ? (await tx.list("contact", (item) => item.externalId === record.externalId))[0]
          : undefined;
      if (local && !record.deleted && hash(this.crmComparable(local, record)) === hash(record.fields)) return "ignored";
      await this.createConflict(tx, organizationId, {
        kind: "crm", provider, aggregateId: local?.id, externalId: record.externalId,
        reason: record.deleted ? "external_deleted" : local ? "external_changed" : "unlinked_external",
        localVersion: local?.version, externalVersion: record.version,
        localPayload: local ? this.crmComparable(local, record) : undefined, externalPayload: record.fields,
      });
      return "conflict";
    });
  }

  private crmComparable(local: object, record: CrmRecord): Record<string, unknown> {
    const values = local as unknown as Record<string, unknown>;
    return Object.fromEntries(Object.keys(record.fields).filter((key) => key in values).map((key) => [key, values[key]]));
  }

  private async createConflict(tx: WorkflowTransaction, organizationId: string, input: Omit<SyncConflict, "id" | "organizationId" | "createdAt" | "updatedAt" | "version" | "status" | "detectedAt">) {
    const duplicate = (await tx.list("syncConflict", (item) => item.status === "pending" && item.provider === input.provider && item.externalId === input.externalId && item.externalVersion === input.externalVersion && item.reason === input.reason))[0];
    if (duplicate) return;
    const timestamp = this.now().toISOString();
    const conflict: SyncConflict = { id: randomUUID(), organizationId, createdAt: timestamp, updatedAt: timestamp, version: 1, status: "pending", detectedAt: timestamp, ...input };
    await tx.insert("syncConflict", conflict);
    await tx.appendEvent({ id: randomUUID(), organizationId, type: "sync.conflict.detected", aggregateId: conflict.aggregateId ?? conflict.id, occurredAt: timestamp, payload: { conflictId: conflict.id, kind: conflict.kind, provider: conflict.provider, reason: conflict.reason } });
  }

  private async getCursor(organizationId: string, provider: string, connectionId: string) {
    return this.storage.transact(organizationId, async (tx) => (await tx.list("syncCursor", (item) => item.provider === provider && item.connectionId === connectionId))[0]);
  }

  private async saveCursor(organizationId: string, provider: string, connectionId: string, cursor?: string) {
    await this.storage.transact(organizationId, async (tx) => {
      const current = (await tx.list("syncCursor", (item) => item.provider === provider && item.connectionId === connectionId))[0];
      const timestamp = this.now().toISOString();
      if (current) await tx.update("syncCursor", { ...current, cursor, lastPulledAt: timestamp, lastErrorCode: undefined, updatedAt: timestamp }, current.version);
      else { const value: SyncCursor = { id: randomUUID(), organizationId, createdAt: timestamp, updatedAt: timestamp, version: 1, provider, connectionId, cursor, lastPulledAt: timestamp }; await tx.insert("syncCursor", value); }
    });
  }
}
