import { z } from "zod";
import type { AccountSnapshot, SalesCall, SalesCycle } from "./schema.js";
import { sanitizeExternalText } from "./security.js";

export const plannerBoundarySchema=z.object({planningMode:z.literal("single"),accountName:z.string().max(120),contactNames:z.array(z.string().min(1).max(120)).max(25),accountType:z.string().min(1).max(80),contactTitle:z.string().min(1).max(100),diseaseFocus:z.string().min(1).max(120),visitObjective:z.string().min(1).max(500),scheduledAt:z.string().datetime(),durationMinutes:z.number().int().min(5).max(480),timezone:z.string().min(1).max(80),location:z.string().max(500).optional(),remindersMinutes:z.array(z.number().int().min(0).max(40_320)).max(5),accountContext:z.string().max(20_000).optional()}).strict();
export const discoveryBoundarySchema=z.object({accountType:z.string().min(1).max(100),diseaseFocus:z.string().min(1).max(120),contactRole:z.string().min(1).max(100),methodology:z.enum(["consultative","spin","challenger","patient-access"])}).strict();
export const objectionBoundarySchema=z.object({objectionCategory:z.enum(["timing","cost","eligibility","service","relationship","competition","other"]),objection:z.string().max(1_000).optional(),accountType:z.string().min(1).max(100),diseaseFocus:z.string().min(1).max(120),difficulty:z.enum(["foundational","intermediate","advanced"])}).strict();
export const performanceBoundarySchema=z.object({transcript:z.string().min(20).max(60_000),context:z.string().min(1).max(2_000),callType:z.enum(["first-call","follow-up","service-recovery","education","referral-development"]),prospectType:z.string().max(100).optional(),consentConfirmed:z.boolean()}).strict();
const criterion=z.object({id:z.string().min(1),name:z.string().min(1),description:z.string().min(1),weight:z.number().positive().max(100)}).strict();
export const coachingBoundarySchema=z.object({prompt:z.string().min(1).max(4_000),response:z.string().min(1).max(8_000),rubric:z.object({name:z.string().min(1),criteria:z.array(criterion).min(1).max(12)}).strict()}).strict();
export const emailBoundarySchema=z.object({prospectType:z.string().min(1).max(100),situation:z.string().min(1).max(2_000),objective:z.string().min(1).max(500),tone:z.enum(["warm","concise","educational","consultative","direct"]),previousInteraction:z.string().max(2_000).optional(),accountHistory:z.array(z.string().min(1).max(500)).max(20).optional(),includeSequence:z.boolean()}).strict();
export const roleplayScenarioBoundarySchema=z.object({scenario:z.string().min(1).max(1_000),personality:z.enum(["analytical","skeptical","busy","relationship-focused","guarded"]),difficulty:z.enum(["foundational","intermediate","advanced"]),accountType:z.string().max(100).optional(),contactRole:z.string().max(100).optional()}).strict();
export const roleplayScenarioOutputBoundarySchema=z.object({scenarioSetup:z.string().min(1),prospectProfile:z.object({name:z.string().min(1),role:z.string().min(1),personality:z.string().min(1),priorities:z.array(z.string()),concerns:z.array(z.string())}).strict(),conversationFlow:z.array(z.object({stage:z.string().min(1),prospectOpening:z.string().min(1),objective:z.string().min(1),likelyChallenge:z.string().min(1),coachingTip:z.string().min(1)}).strict()).min(1),successMetrics:z.array(z.string()).min(1),openingLine:z.string().min(1)}).strict();
export const adaptiveRoleplayBoundarySchema=z.object({stage:z.string().min(1).max(120),userInput:z.string().min(1).max(4_000),conversationHistory:z.array(z.object({role:z.enum(["learner","prospect"]),content:z.string().min(1).max(4_000)}).strict()).max(40),scenario:z.object({scenarioSetup:z.string().min(1),prospectProfile:z.object({name:z.string(),role:z.string(),personality:z.string(),priorities:z.array(z.string()),concerns:z.array(z.string())}).strict(),successMetrics:z.array(z.string())}).strict()}).strict();
export const adaptiveRoleplayOutputBoundarySchema=z.object({prospectResponse:z.string().min(1),coachingTip:z.string().min(1),emotionalTone:z.enum(["open","neutral","skeptical","concerned","frustrated","reassured"]),difficultyAdjustment:z.enum(["easier","same","harder"]),evaluation:z.object({score:z.number(),empathy:z.number(),discovery:z.number(),clarity:z.number(),evidence:z.array(z.string()),nextMove:z.string()}).strict(),sessionComplete:z.boolean()}).strict();

const text=(value:string|undefined,fallback:string,max:number)=>sanitizeExternalText(value?.trim()||fallback,max);
export function buildPlannerInput(snapshot:AccountSnapshot,call:SalesCall,cycle:SalesCycle,context:string){const contacts=snapshot.contacts.filter(item=>call.contactIds.includes(item.id));return plannerBoundarySchema.parse({planningMode:"single",accountName:snapshot.account.name,contactNames:contacts.map(item=>`${item.firstName} ${item.lastName}`.trim()),accountType:text(snapshot.account.accountType,"healthcare",80),contactTitle:text(contacts.map(item=>item.title).filter(Boolean).join(", "),"healthcare contact",100),diseaseFocus:text(cycle.diseaseFocus,"hospice education",120),visitObjective:text(call.purpose,"Plan the next conversation",500),scheduledAt:call.schedule.startsAt,durationMinutes:call.schedule.durationMinutes,timezone:call.schedule.timezone,location:call.schedule.location,remindersMinutes:call.schedule.remindersMinutes,accountContext:context});}
export function buildDiscoveryInput(snapshot:AccountSnapshot,call:SalesCall,cycle:SalesCycle){const contacts=snapshot.contacts.filter(item=>call.contactIds.includes(item.id));return discoveryBoundarySchema.parse({accountType:text(snapshot.account.accountType,"healthcare",100),diseaseFocus:text(cycle.diseaseFocus,"hospice education",120),contactRole:text(contacts[0]?.title,"healthcare contact",100),methodology:"patient-access"});}
export function buildObjectionInput(snapshot:AccountSnapshot,cycle:SalesCycle,plannerOutput:unknown){const likely=(plannerOutput as {likelyObjections?:Array<{objection?:string}>})?.likelyObjections?.[0]?.objection;return objectionBoundarySchema.parse({objectionCategory:"other",objection:likely?text(likely,"",1_000):undefined,accountType:text(snapshot.account.accountType,"healthcare",100),diseaseFocus:text(cycle.diseaseFocus,"hospice education",120),difficulty:"intermediate"});}
export function buildPerformanceInput(call:SalesCall,raw:string,consentConfirmed:boolean,hasPriorCall:boolean){const transcript=text(`Call outcome context. ${raw}`,"Call completed without a detailed transcript.",60_000);return performanceBoundarySchema.parse({transcript:transcript.length>=20?transcript:transcript.padEnd(20,"."),context:text(call.purpose,"Hospice referral development",2_000),callType:hasPriorCall?"follow-up":"first-call",prospectType:undefined,consentConfirmed});}
export function buildCoachingInput(call:SalesCall,performance:unknown){return coachingBoundarySchema.parse({prompt:text(`Coach this hospice sales call toward: ${call.purpose}`,"Coach this hospice sales call",4_000),response:text(JSON.stringify(performance),"No performance details were returned",8_000),rubric:{name:"Hospice sales call",criteria:[{id:"discovery",name:"Discovery",description:"Uncovers useful needs",weight:35},{id:"empathy",name:"Empathy",description:"Responds with empathy",weight:35},{id:"next-step",name:"Next step",description:"Secures a clear next step",weight:30}]}});}
export function buildEmailInput(snapshot:AccountSnapshot,call:SalesCall,objective:string){return emailBoundarySchema.parse({prospectType:text(snapshot.contacts.find(item=>call.contactIds.includes(item.id))?.title,"healthcare contact",100),situation:text(`Follow-up after: ${call.purpose}`,"Hospice referral-development follow-up",2_000),objective:text(objective,"Confirm the next step",500),tone:"consultative",previousInteraction:text(snapshot.recentActivities[0]?.summary,"Previous hospice sales conversation",2_000),accountHistory:snapshot.recentActivities.slice(0,20).map(item=>text(item.summary,"Account activity",500)),includeSequence:true});}
export function buildRoleplayScenarioInput(snapshot:AccountSnapshot,call:SalesCall,planContent:unknown){const contact=snapshot.contacts.find(item=>call.contactIds.includes(item.id));return roleplayScenarioBoundarySchema.parse({scenario:text(`Practice the planned conversation: ${call.purpose}. Preparation: ${JSON.stringify(planContent)}`,call.purpose,1_000),personality:"guarded",difficulty:"intermediate",accountType:text(snapshot.account.accountType,"healthcare",100),contactRole:text(contact?.title,"healthcare contact",100)});}
export function buildAdaptiveRoleplayInput(session:{scenario:unknown;messages:Array<{role:"learner"|"prospect";content:string}>;turn:number},userInput:string){const scenario=roleplayScenarioOutputBoundarySchema.parse(session.scenario);const stage=scenario.conversationFlow[Math.min(session.turn,scenario.conversationFlow.length-1)]?.stage??"conversation";return adaptiveRoleplayBoundarySchema.parse({stage,userInput:text(userInput,"Continue the conversation",4_000),conversationHistory:[...session.messages,{role:"learner" as const,content:text(userInput,"Continue the conversation",4_000)}].slice(-40),scenario:{scenarioSetup:scenario.scenarioSetup,prospectProfile:scenario.prospectProfile,successMetrics:scenario.successMetrics}});}
