import { createHash, randomUUID } from "node:crypto";
import { completeCallInputSchema, nextCallInputSchema, startCycleInputSchema, type Actor, type AiArtifact, type CallPlan, type CoachingSession, type CompleteCallInput, type EmailDraft, type NextAction, type NextCallInput,type RoleplaySession, type SalesCall, type SalesCycle, type StartCycleInput, type SyncJob } from "./schema.js";
import type { AuthorizationAdapter, Clock, EncryptionAdapter, NotificationAdapter, QueueAdapter, RateLimitAdapter, ToolResult, WorkflowStorage, WorkflowTools } from "./ports.js";
import { DefaultAuthorization, sanitizeExternalText, WorkflowError } from "./security.js";
import { adaptiveRoleplayOutputBoundarySchema, buildAdaptiveRoleplayInput, buildCoachingInput, buildDiscoveryInput, buildEmailInput, buildObjectionInput, buildPerformanceInput, buildPlannerInput, buildRoleplayScenarioInput, roleplayScenarioOutputBoundarySchema } from "./tool-contracts.js";

export interface WorkflowDependencies { storage: WorkflowStorage; tools: WorkflowTools; queue?: QueueAdapter; encryption?: EncryptionAdapter; authorization?: AuthorizationAdapter; rateLimit?: RateLimitAdapter; notifications?: NotificationAdapter; clock?: Clock; promptVersion?: string; schemaVersion?: string;crmSyncEnabled?:boolean; }
const unwrap = <T>(value: ToolResult<T> | T): { output: T; metadata?: ToolResult<T>["metadata"] } => typeof value === "object" && value !== null && "output" in value ? value as ToolResult<T> : { output: value as T };
const hash = (value: unknown) => createHash("sha256").update(JSON.stringify(value)).digest("hex");

export class SalesWorkflowOrchestrator {
  private readonly auth: AuthorizationAdapter; private readonly clock: Clock;
  constructor(private readonly deps: WorkflowDependencies) { this.auth = deps.authorization ?? new DefaultAuthorization(); this.clock = deps.clock ?? { now: () => new Date() }; }
  private now() { return this.clock.now().toISOString(); }
  private base(actor: Actor) { const now = this.now(); return { id: randomUUID(), organizationId: actor.organizationId, createdAt: now, updatedAt: now, version: 1 }; }
  private event(actor: Actor, type: string, aggregateId: string, payload: Record<string, unknown> = {}) { return { id: randomUUID(), organizationId: actor.organizationId, type, aggregateId, occurredAt: this.now(), payload }; }
  private audit(actor: Actor, action: string, aggregateId?: string, metadata: Record<string, unknown> = {}) { return { id: randomUUID(), organizationId: actor.organizationId, actorUserId: actor.userId, action, aggregateId, occurredAt: this.now(), metadata }; }
  private syncJob(actor: Actor, kind: "calendar" | "crm", aggregateId: string, key: string): SyncJob { return { ...this.base(actor), kind, aggregateId, status: "queued", attempts: 0, availableAt: this.now(), idempotencyKey: key }; }
  private artifact(toolId: string, result: { output: unknown; metadata?: ToolResult<unknown>["metadata"] }, capturedAt: string, sources: string[], warnings: string[] = []): AiArtifact { return { status: "draft", toolId, promptVersion: this.deps.promptVersion ?? "workflow-v1", schemaVersion: this.deps.schemaVersion ?? "1", model: result.metadata?.model, responseId: result.metadata?.responseId, usage: result.metadata?.usage, contextCapturedAt: capturedAt, sources, warnings, output: result.output }; }

  async startCycle(raw: StartCycleInput, actor: Actor): Promise<{ cycle: SalesCycle; call: SalesCall; plan: CallPlan }> {
    const input = startCycleInputSchema.parse(raw); await this.auth.assert(actor, "cycle:create", { organizationId: actor.organizationId, ownerUserId: input.account.ownerUserId });
    const result = await this.deps.storage.transact(actor.organizationId, async (tx) => {
      const named = input.account.id ? [] : await tx.list("account", (item) => item.name.toLocaleLowerCase() === input.account.name.toLocaleLowerCase() && !item.deletedAt);const existing = input.account.id ? await tx.get("account", input.account.id) : named[0];
      if(input.account.id&&!existing)throw new WorkflowError("NOT_FOUND",404,"Selected account was not found");if(existing)await this.auth.assert(actor,"account:use",existing);
      const account = existing ?? { ...this.base(actor), name: input.account.name, accountType: input.account.accountType, address: input.account.address, territoryId: input.account.territoryId, ownerUserId: input.account.ownerUserId, externalId: input.account.externalId };
      if (!existing) await tx.insert("account", account);
      const contacts = [];const existingContacts=await tx.list("contact",item=>item.accountId===account.id);
      for (const item of input.account.contacts) { const duplicate=existingContacts.find(current=>item.externalId&&current.externalId===item.externalId||item.email&&current.email?.toLocaleLowerCase()===item.email.toLocaleLowerCase()||current.firstName.toLocaleLowerCase()===item.firstName.toLocaleLowerCase()&&current.lastName.toLocaleLowerCase()===item.lastName.toLocaleLowerCase());if(duplicate){contacts.push(duplicate);continue}const contact = { ...this.base(actor), ...(item.id ? { id: item.id } : {}), accountId: account.id, firstName: item.firstName, lastName: item.lastName, title: item.title, email: item.email, phone: item.phone, isPrimary: item.isPrimary, externalId: item.externalId }; await tx.insert("contact", contact); contacts.push(contact);existingContacts.push(contact); }
      if(input.contactIds.length){const selected=await Promise.all(input.contactIds.map(id=>tx.get("contact",id)));if(selected.some(item=>!item||item.accountId!==account.id))throw new WorkflowError("INVALID_CONTACT",400,"Every selected contact must belong to the selected account");}
      const cycle: SalesCycle = { ...this.base(actor), accountId: account.id, ownerUserId: input.account.ownerUserId, purpose: input.purpose, diseaseFocus: input.diseaseFocus, status: "active" };
      const call: SalesCall = { ...this.base(actor), cycleId: cycle.id, accountId: account.id, ownerUserId: input.account.ownerUserId, contactIds: input.contactIds.length ? input.contactIds : contacts.filter((item) => item.isPrimary).map((item) => item.id), purpose: input.purpose, schedule: input.schedule, status: "scheduled" };
      const plan: CallPlan = { ...this.base(actor), cycleId: cycle.id, callId: call.id, status: "draft" };
      await tx.insert("cycle", cycle); await tx.insert("call", call); await tx.insert("plan", plan);const calendarJob=call.schedule.calendarProvider?this.syncJob(actor,"calendar",call.id,`calendar:schedule:${call.id}:1`):undefined;const crmJob=this.deps.crmSyncEnabled?this.syncJob(actor,"crm",call.id,`crm:schedule:${call.id}:1`):undefined;if(calendarJob)await tx.insert("syncJob",calendarJob);if(crmJob)await tx.insert("syncJob",crmJob);
      await tx.appendEvent(this.event(actor, "call.plan.created", plan.id, { cycleId: cycle.id, callId: call.id }));if(calendarJob)await tx.appendEvent(this.event(actor,"calendar.sync.requested",call.id,{syncJobId:calendarJob.id}));if(crmJob)await tx.appendEvent(this.event(actor,"crm.sync.requested",call.id,{syncJobId:crmJob.id})); await tx.appendAudit(this.audit(actor, "cycle.created", cycle.id));
      return { cycle, call, plan };
    }); return result;
  }

  async buildPlan(planId: string, expectedVersion: number, actor: Actor): Promise<CallPlan> {
    await this.deps.rateLimit?.consume(actor.organizationId, actor.userId, "workflow:build-plan");
    const context = await this.deps.storage.transact(actor.organizationId, async (tx) => { const plan = await tx.get("plan", planId); if (!plan) throw new WorkflowError("NOT_FOUND", 404, "Plan not found"); const call = await tx.get("call", plan.callId); const cycle = await tx.get("cycle", plan.cycleId); if (!call || !cycle) throw new WorkflowError("BROKEN_WORKFLOW", 500, "Plan workflow is incomplete"); await this.auth.assert(actor, "plan:build", call); return { plan, call, cycle }; });
    if (context.plan.version !== expectedVersion) throw new WorkflowError("VERSION_CONFLICT", 409, "Plan changed; refresh and try again");
    const snapshot = await this.deps.storage.snapshot(context.call.accountId, actor);
    const externalContext = sanitizeExternalText(JSON.stringify({ account: snapshot.account, contacts:snapshot.contacts.filter(item=>context.call.contactIds.includes(item.id)), activities: snapshot.recentActivities }), 20_000);
    const planner = unwrap(await this.deps.tools.planner.run(buildPlannerInput(snapshot,context.call,context.cycle,externalContext), { userId: actor.userId }));
    const discovery = unwrap(await this.deps.tools.discovery.run(buildDiscoveryInput(snapshot,context.call,context.cycle), { userId: actor.userId }));
    const objection = unwrap(await this.deps.tools.objection.run(buildObjectionInput(snapshot,context.cycle,planner.output), { userId: actor.userId }));
    const output = { planner: planner.output, discovery: discovery.output, objection: objection.output };
    return this.deps.storage.transact(actor.organizationId, async (tx) => { const current = await tx.get("plan", planId); if (!current) throw new WorkflowError("NOT_FOUND", 404, "Plan not found"); const updated: CallPlan = { ...current, status: "ready", updatedAt: this.now(), content: output, artifact: this.artifact("pre-call-workflow", { output, metadata: planner.metadata }, snapshot.capturedAt, snapshot.sourceIds) }; await tx.update("plan", updated, expectedVersion); await tx.appendEvent(this.event(actor, "call.plan.ready", planId, { callId: current.callId })); await tx.appendAudit(this.audit(actor, "plan.generated", planId, { contextHash: hash(snapshot.sourceIds) })); return { ...updated, version: expectedVersion + 1 }; });
  }

  async startCall(callId: string, expectedVersion: number, actor: Actor): Promise<SalesCall> {
    return this.deps.storage.transact(actor.organizationId, async (tx) => { const call = await tx.get("call", callId); if (!call) throw new WorkflowError("NOT_FOUND", 404, "Call not found"); await this.auth.assert(actor, "call:start", call); if (!["scheduled", "confirmed"].includes(call.status)) throw new WorkflowError("INVALID_STATE", 409, "Only a scheduled or confirmed call can start"); const updated = { ...call, status: "in_progress" as const, updatedAt: this.now() }; await tx.update("call", updated, expectedVersion); await tx.appendAudit(this.audit(actor, "call.started", callId)); return { ...updated, version: expectedVersion + 1 }; });
  }

  async startRoleplay(planId:string,expectedVersion:number,actor:Actor):Promise<RoleplaySession>{if(!this.deps.tools.roleplayScenario||!this.deps.tools.adaptiveRoleplay)throw new WorkflowError("ROLEPLAY_DISABLED",404,"Roleplay tools are not configured");const context=await this.deps.storage.transact(actor.organizationId,async(tx)=>{const plan=await tx.get("plan",planId);if(!plan)throw new WorkflowError("NOT_FOUND",404,"Plan not found");if(plan.version!==expectedVersion)throw new WorkflowError("VERSION_CONFLICT",409,"Plan changed; refresh and try again");if(plan.status!=="ready")throw new WorkflowError("PLAN_NOT_READY",409,"Build the pre-call plan before starting roleplay");const call=await tx.get("call",plan.callId);if(!call)throw new WorkflowError("BROKEN_WORKFLOW",500,"Call is missing");await this.auth.assert(actor,"roleplay:start",call);return{plan,call}});const snapshot=await this.deps.storage.snapshot(context.call.accountId,actor);const result=unwrap(await this.deps.tools.roleplayScenario.run(buildRoleplayScenarioInput(snapshot,context.call,context.plan.content),{userId:actor.userId}));const scenario=roleplayScenarioOutputBoundarySchema.parse(result.output);return this.deps.storage.transact(actor.organizationId,async(tx)=>{const session:RoleplaySession={...this.base(actor),cycleId:context.call.cycleId,planId:context.plan.id,ownerUserId:context.call.ownerUserId,scenario,messages:[{role:"prospect",content:scenario.openingLine}],turn:0,complete:false};await tx.insert("roleplaySession",session);await tx.appendAudit(this.audit(actor,"roleplay.started",session.id,{planId}));return session});}

  async continueRoleplay(sessionId:string,expectedVersion:number,userInput:string,actor:Actor):Promise<RoleplaySession>{if(!this.deps.tools.adaptiveRoleplay)throw new WorkflowError("ROLEPLAY_DISABLED",404,"Adaptive roleplay is not configured");const session=await this.deps.storage.transact(actor.organizationId,async(tx)=>{const value=await tx.get("roleplaySession",sessionId);if(!value)throw new WorkflowError("NOT_FOUND",404,"Roleplay session not found");await this.auth.assert(actor,"roleplay:continue",value);if(value.version!==expectedVersion)throw new WorkflowError("VERSION_CONFLICT",409,"Roleplay changed; refresh and try again");if(value.complete)throw new WorkflowError("ROLEPLAY_COMPLETE",409,"This roleplay is complete");return value});const input=buildAdaptiveRoleplayInput(session,userInput);const result=unwrap(await this.deps.tools.adaptiveRoleplay.run(input,{userId:actor.userId}));const coaching=adaptiveRoleplayOutputBoundarySchema.parse(result.output);return this.deps.storage.transact(actor.organizationId,async(tx)=>{const current=await tx.get("roleplaySession",sessionId);if(!current)throw new WorkflowError("NOT_FOUND",404,"Roleplay session not found");const updated:RoleplaySession={...current,messages:[...input.conversationHistory,{role:"prospect",content:coaching.prospectResponse}],turn:current.turn+1,latestCoaching:coaching,complete:coaching.sessionComplete,updatedAt:this.now()};await tx.update("roleplaySession",updated,expectedVersion);await tx.appendAudit(this.audit(actor,"roleplay.turn.completed",sessionId,{turn:updated.turn,complete:updated.complete}));return{...updated,version:expectedVersion+1}});}

  async completeCall(raw: CompleteCallInput, actor: Actor): Promise<{ call: SalesCall; coaching: CoachingSession; nextActions: NextAction[] }> {
    const input = completeCallInputSchema.parse(raw); const existing = await this.deps.storage.transact(actor.organizationId, async (tx) => { const call = await tx.get("call", input.callId); if (!call) throw new WorkflowError("NOT_FOUND", 404, "Call not found"); await this.auth.assert(actor, "call:complete", call); return call; });
    const terminal = input.outcome === "no_show" ? "no_show" : input.outcome === "canceled" ? "canceled" : "completed";
    const encryptedTranscript = input.transcript ? this.deps.encryption ? await this.deps.encryption.encrypt(input.transcript, `transcript:${input.callId}`) : undefined : undefined;
    if (input.transcript && !this.deps.encryption) throw new WorkflowError("ENCRYPTION_REQUIRED", 503, "Transcript storage requires encryption");
    const committed = await this.deps.storage.transact(actor.organizationId, async (tx) => { const call = await tx.get("call", input.callId); if (!call) throw new WorkflowError("NOT_FOUND", 404, "Call not found"); if (!["scheduled", "confirmed", "in_progress"].includes(call.status)) throw new WorkflowError("INVALID_STATE", 409, "Call is already closed"); const updated: SalesCall = { ...call, status: terminal, updatedAt: this.now() }; await tx.update("call", updated, input.expectedVersion); const outcome = { ...this.base(actor), callId: call.id, outcome: input.outcome, notes: input.notes, summary: input.summary, encryptedTranscript, consentConfirmed: input.consentConfirmed, commitments: input.commitments, referralSignals: input.referralSignals }; await tx.insert("outcome", outcome); await tx.insert("activity", { ...this.base(actor), accountId: call.accountId, cycleId: call.cycleId, type: "call_completed", summary: input.summary ?? `Call marked ${terminal}`, occurredAt: this.now(), actorUserId: actor.userId }); const calendarJob = call.schedule.calendarProvider?this.syncJob(actor, "calendar", call.id, `calendar:complete:${call.id}:${input.expectedVersion}`):undefined; const crmJob = this.deps.crmSyncEnabled?this.syncJob(actor, "crm", call.id, `crm:complete:${call.id}:${input.expectedVersion}`):undefined; if(calendarJob)await tx.insert("syncJob", calendarJob); if(crmJob)await tx.insert("syncJob", crmJob); await tx.appendEvent(this.event(actor, "call.completed", call.id, { outcomeId: outcome.id, status: terminal })); if(calendarJob)await tx.appendEvent(this.event(actor, "calendar.sync.requested", call.id, { syncJobId: calendarJob.id })); if(crmJob)await tx.appendEvent(this.event(actor, "crm.sync.requested", call.id, { syncJobId: crmJob.id })); await tx.appendAudit(this.audit(actor, "call.completed", call.id, { consentConfirmed: input.consentConfirmed, transcriptPresent: Boolean(input.transcript) })); return { call: { ...updated, version: input.expectedVersion + 1 }, outcome }; });
    const analysisText = input.transcript ?? input.summary ?? input.notes ?? `Call outcome: ${input.outcome}`;const beforeSnapshot=await this.deps.storage.snapshot(existing.accountId,actor);const hasPriorCall=beforeSnapshot.recentActivities.filter(item=>item.type==="call_completed").length>1;let performance:{output:unknown;metadata?:ToolResult<unknown>["metadata"]};let coachingResult:{output:unknown;metadata?:ToolResult<unknown>["metadata"]};let aiWarnings:string[]=[];
    if(["no_show","canceled"].includes(input.outcome)){performance={output:{analysisSkipped:true,reason:input.outcome}};coachingResult={output:{improvements:[input.outcome==="no_show"?"Reschedule the missed conversation":"Confirm whether a new conversation is appropriate"]}};aiWarnings=["AI analysis was skipped because no completed conversation occurred"]}else{try{performance=unwrap(await this.deps.tools.callPerformance.run(buildPerformanceInput(existing,analysisText,input.consentConfirmed,hasPriorCall), { userId: actor.userId }));coachingResult=unwrap(await this.deps.tools.coaching.run(buildCoachingInput(existing,performance.output), { userId: actor.userId }));}catch{performance={output:{analysisUnavailable:true}};coachingResult={output:{improvements:["Review the call manually and confirm the next step"]}};aiWarnings=["AI coaching was unavailable; the completed call remains saved and requires manual review"]}}
    const snapshot = await this.deps.storage.snapshot(existing.accountId, actor);
    const final = await this.deps.storage.transact(actor.organizationId, async (tx) => { const coaching: CoachingSession = { ...this.base(actor), callId: existing.id, status: "draft", performance: this.artifact("call-performance-coach", performance, snapshot.capturedAt, snapshot.sourceIds,aiWarnings), coaching: this.artifact("coaching-feedback", coachingResult, snapshot.capturedAt, snapshot.sourceIds,aiWarnings) }; await tx.insert("coaching", coaching); const cycle=await tx.get("cycle",existing.cycleId);if(!cycle)throw new WorkflowError("BROKEN_WORKFLOW",500,"Sales cycle is missing");const output = coachingResult.output as Record<string, unknown>; const suggestions = Array.isArray(output.improvements) ? output.improvements.slice(0, 3).map(String) : ["Review coaching and choose the next step"];
      const nextActions: NextAction[] = suggestions.map((title, index) => ({ ...this.base(actor), cycleId: existing.cycleId, cycleVersion:cycle.version, callId: existing.id, type: index === 0 ? "next_call" : index === 1 ? "email" : "task", status: "proposed", title, sourceCoachingId: coaching.id })); for (const action of nextActions) await tx.insert("nextAction", action); await tx.appendEvent(this.event(actor, "coaching.generated", coaching.id, { callId: existing.id, nextActionIds: nextActions.map((item) => item.id) })); await tx.appendAudit(this.audit(actor, "coaching.generated", coaching.id)); return { coaching, nextActions }; });
    return { call: committed.call, ...final };
  }

  async approveCoaching(coachingId: string, expectedVersion: number, acceptedActionIds: string[], actor: Actor): Promise<{ coaching: CoachingSession; actions: NextAction[] }> {
    return this.deps.storage.transact(actor.organizationId, async (tx) => { const coaching = await tx.get("coaching", coachingId); if (!coaching) throw new WorkflowError("NOT_FOUND", 404, "Coaching not found"); const call = await tx.get("call", coaching.callId); if (!call) throw new WorkflowError("NOT_FOUND", 404, "Call not found"); await this.auth.assert(actor, "coaching:approve", call); const updated: CoachingSession = { ...coaching, status: "rep_approved", approvedBy: actor.userId, approvedAt: this.now(), updatedAt: this.now() }; await tx.update("coaching", updated, expectedVersion); const actions = await tx.list("nextAction", (item) => item.sourceCoachingId === coachingId); const accepted: NextAction[] = []; for (const action of actions) { const status = acceptedActionIds.includes(action.id) ? "accepted" : "dismissed"; const next = { ...action, status, updatedAt: this.now() } as NextAction; await tx.update("nextAction", next, action.version); if (status === "accepted") accepted.push({ ...next, version: action.version + 1 }); } await tx.appendEvent(this.event(actor, "coaching.approved", coachingId, { acceptedActionIds })); await tx.appendAudit(this.audit(actor, "coaching.approved", coachingId)); return { coaching: { ...updated, version: expectedVersion + 1 }, actions: accepted }; });
  }

  async scheduleNextCall(raw: NextCallInput, actor: Actor): Promise<{ call: SalesCall; plan: CallPlan }> {
    const input = nextCallInputSchema.parse(raw); const result = await this.deps.storage.transact(actor.organizationId, async (tx) => { const cycle = await tx.get("cycle", input.cycleId); if (!cycle) throw new WorkflowError("NOT_FOUND", 404, "Sales cycle not found"); await this.auth.assert(actor, "call:schedule-next", cycle); if (cycle.version !== input.expectedVersion) throw new WorkflowError("VERSION_CONFLICT", 409, "Sales cycle changed; refresh and try again"); const account = await tx.get("account", cycle.accountId); if (!account) throw new WorkflowError("NOT_FOUND", 404, "Account not found"); const call: SalesCall = { ...this.base(actor), cycleId: cycle.id, accountId: account.id, ownerUserId: cycle.ownerUserId, contactIds: input.contactIds, purpose: input.purpose, schedule: input.schedule, status: "scheduled" }; const plan: CallPlan = { ...this.base(actor), cycleId: cycle.id, callId: call.id, status: "draft" }; await tx.insert("call", call); await tx.insert("plan", plan); if (input.nextActionId) { const action = await tx.get("nextAction", input.nextActionId); if (!action || action.cycleId !== cycle.id) throw new WorkflowError("NOT_FOUND", 404, "Next action not found"); await tx.update("nextAction", { ...action, status: "scheduled", dueAt: input.schedule.startsAt, updatedAt: this.now() }, action.version); } const calendarJob = call.schedule.calendarProvider?this.syncJob(actor, "calendar", call.id, `calendar:schedule:${call.id}:1`):undefined; const crmJob = this.deps.crmSyncEnabled?this.syncJob(actor, "crm", call.id, `crm:schedule:${call.id}:1`):undefined; if(calendarJob)await tx.insert("syncJob", calendarJob); if(crmJob)await tx.insert("syncJob", crmJob); await tx.appendEvent(this.event(actor, "next_call.scheduled", call.id, { cycleId: cycle.id, planId: plan.id })); if(calendarJob)await tx.appendEvent(this.event(actor, "calendar.sync.requested", call.id, { syncJobId: calendarJob.id })); if(crmJob)await tx.appendEvent(this.event(actor, "crm.sync.requested", call.id, { syncJobId: crmJob.id })); await tx.appendAudit(this.audit(actor, "next_call.scheduled", call.id)); return { call, plan }; }); await this.deps.notifications?.notify(result.call.ownerUserId, { title: "Next call scheduled", body: result.call.purpose, href: `/calls/${result.call.id}` }); return result;
  }

  async generateEmailDraft(nextActionId: string, expectedVersion: number, actor: Actor): Promise<EmailDraft> {
    if (!this.deps.tools.email) throw new WorkflowError("EMAIL_TOOL_DISABLED", 404, "Email drafting is not configured");
    const context = await this.deps.storage.transact(actor.organizationId, async (tx) => { const action=await tx.get("nextAction",nextActionId);if(!action||action.type!=="email")throw new WorkflowError("NOT_FOUND",404,"Email action not found");const call=await tx.get("call",action.callId);if(!call)throw new WorkflowError("NOT_FOUND",404,"Call not found");await this.auth.assert(actor,"email:draft",call);if(action.version!==expectedVersion)throw new WorkflowError("VERSION_CONFLICT",409,"Next action changed; refresh and try again");return{action,call}; });
    const snapshot=await this.deps.storage.snapshot(context.call.accountId,actor);const result=unwrap(await this.deps.tools.email.run(buildEmailInput(snapshot,context.call,context.action.title),{userId:actor.userId}));
    return this.deps.storage.transact(actor.organizationId,async(tx)=>{const output=result.output as {templates?:Array<{subject?:string;body?:string}>};const primary=output.templates?.[0];const draft:EmailDraft={...this.base(actor),cycleId:context.action.cycleId,callId:context.call.id,nextActionId:context.action.id,status:"draft",toContactIds:context.call.contactIds,subject:primary?.subject,body:primary?.body,artifact:this.artifact("email-optimizer",result,snapshot.capturedAt,snapshot.sourceIds,["A/B result is simulated until connected to a real experiment"]),simulatedAbResult:true};await tx.insert("emailDraft",draft);await tx.appendAudit(this.audit(actor,"email.draft.generated",draft.id,{simulatedAbResult:true}));return draft;});
  }

  async getToday(actor: Actor, from: string, to: string) { await this.auth.assert(actor, "today:view", { organizationId: actor.organizationId }); return this.deps.storage.today(actor, from, to); }
}
