  async deleteEvent(input: { connectionId: string; externalId: string; expectedEtag?: string }) { const token = await this.auth(input.connectionId); checked(await this.transport.request(`https://www.googleapis.com/calendar/v3/calendars/primary/events/${encodeURIComponent(input.externalId)}`, { method: "DELETE", headers: { Authorization: `Bearer ${token}`, ...(input.expectedEtag ? { "If-Match": input.expectedEtag } : {}) } }), [204]); }
  async renewSubscription(input: { connectionId: string; callbackUrl: string }) { const token = await this.auth(input.connectionId); const id = createHash("sha256").update(`${input.connectionId}:${Date.now()}`).digest("hex").slice(0, 32); const expiration = Date.now() + 6 * 24 * 60 * 60_000; checked(await this.transport.request("https://www.googleapis.com/calendar/v3/calendars/primary/events/watch", { method: "POST", headers: { Authorization: `Bearer ${token}`, "Content-Type": "application/json" }, body: JSON.stringify({ id, type: "web_hook", address: input.callbackUrl, expiration: String(expiration) }) })); return { expiresAt: new Date(expiration).toISOString() }; }
  async disconnect(connectionId: string) { await this.tokens.revoke(connectionId); }
