export class OutlookCalendarAdapter implements CalendarAdapter {
  constructor(private readonly clientId: string, private readonly tokens: CalendarTokenStore, private readonly transport: HttpTransport = fetchTransport) {}
  async connect(input: { redirectUri: string; state: string; scopes?: string[] }): Promise<CalendarConnection> { const query = new URLSearchParams({ client_id: this.clientId, redirect_uri: input.redirectUri, response_type: "code", response_mode: "query", state: input.state, scope: (input.scopes ?? ["offline_access", "Calendars.ReadWrite"]).join(" ") }); return { authorizationUrl: `https://login.microsoftonline.com/common/oauth2/v2.0/authorize?${query}`, state: input.state }; }
  private async auth(connectionId: string) { return (await this.tokens.get(connectionId)).accessToken; }
  async listChanges(input: { connectionId: string; cursor?: string;windowStart?:string;windowEnd?:string }) { const token = await this.auth(input.connectionId);const start=input.windowStart??new Date(Date.now()-90*86_400_000).toISOString();const end=input.windowEnd??new Date(Date.now()+365*86_400_000).toISOString(); const url = input.cursor ?? `https://graph.microsoft.com/v1.0/me/calendarView/delta?${new URLSearchParams({startDateTime:start,endDateTime:end})}`; const response=await this.transport.request<{ value?: Array<Record<string, any>>; "@odata.deltaLink"?: string; "@odata.nextLink"?: string }>(url, { headers: { Authorization: `Bearer ${token}` } });if(response.status===410)throw new WorkflowError("SYNC_CURSOR_EXPIRED",409,"Outlook sync cursor expired; run a full resync");const data = checked(response); const changes: CalendarChange[] = (data.value ?? []).map((item) => {const startsAt=item.start?.dateTime;const endsAt=item.end?.dateTime;const durationMinutes=startsAt&&endsAt?Math.max(5,Math.round((new Date(endsAt).getTime()-new Date(startsAt).getTime())/60_000)):undefined;return{ externalId: String(item.id), etag: typeof item["@odata.etag"] === "string" ? String(item["@odata.etag"]) : undefined, deleted: "@removed" in item, updatedAt: String(item.lastModifiedDateTime ?? new Date().toISOString()),payload:startsAt&&durationMinutes?{title:String(item.subject??"Calendar event"),description:typeof item.bodyPreview==="string"?item.bodyPreview:undefined,startsAt,durationMinutes,timezone:String(item.start?.timeZone??"UTC"),location:typeof item.location?.displayName==="string"?item.location.displayName:undefined,remindersMinutes:item.isReminderOn?[Number(item.reminderMinutesBeforeStart??30)]:[],originId:typeof item.transactionId==="string"?item.transactionId:`external:${String(item.id)}`,syncRevision:0}:undefined}}); return { changes, cursor: data["@odata.deltaLink"] ?? data["@odata.nextLink"] }; }
  async upsertEvent(input: { connectionId: string; event: CalendarUpsert; externalId?: string; expectedEtag?: string }) { const token = await this.auth(input.connectionId); const body = { subject: input.event.title, body: { contentType: "text", content: `${input.event.description ?? ""}\n[workflow:${input.event.originId}:${input.event.syncRevision}]` }, start: { dateTime: input.event.startsAt.replace(/Z$/, ""), timeZone: input.event.timezone }, end: { dateTime: endAt(input.event).replace(/Z$/, ""), timeZone: input.event.timezone }, location: input.event.location ? { displayName: input.event.location } : undefined, reminderMinutesBeforeStart: input.event.remindersMinutes[0] ?? 30, isReminderOn: input.event.remindersMinutes.length > 0, transactionId: input.event.originId }; const url = `https://graph.microsoft.com/v1.0/me/events${input.externalId ? `/${encodeURIComponent(input.externalId)}` : ""}`; const response = await this.transport.request<{ id: string; "@odata.etag"?: string }>(url, { method: input.externalId ? "PATCH" : "POST", headers: { Authorization: `Bearer ${token}`, "Content-Type": "application/json", ...(input.expectedEtag ? { "If-Match": input.expectedEtag } : {}) }, body: JSON.stringify(body) }); const data = checked(response); return { externalId: data.id, etag: data["@odata.etag"] }; }
  async deleteEvent(input: { connectionId: string; externalId: string; expectedEtag?: string }) { const token = await this.auth(input.connectionId); checked(await this.transport.request(`https://graph.microsoft.com/v1.0/me/events/${encodeURIComponent(input.externalId)}`, { method: "DELETE", headers: { Authorization: `Bearer ${token}`, ...(input.expectedEtag ? { "If-Match": input.expectedEtag } : {}) } }), [204]); }
  async renewSubscription(input: { connectionId: string; callbackUrl: string }) { const token = await this.auth(input.connectionId); const expiration = Date.now() + 2 * 24 * 60 * 60_000; checked(await this.transport.request("https://graph.microsoft.com/v1.0/subscriptions", { method: "POST", headers: { Authorization: `Bearer ${token}`, "Content-Type": "application/json" }, body: JSON.stringify({ changeType: "created,updated,deleted", notificationUrl: input.callbackUrl, resource: "/me/events", expirationDateTime: new Date(expiration).toISOString(), clientState: createHash("sha256").update(input.connectionId).digest("hex") }) })); return { expiresAt: new Date(expiration).toISOString() }; }
  async disconnect(connectionId: string) { await this.tokens.revoke(connectionId); }
}
