import { z } from "zod";

export const roleSchema = z.enum(["rep", "manager", "integration_admin"]);
export const planStatusSchema = z.enum(["draft", "ready", "scheduled", "superseded", "archived"]);
export const callStatusSchema = z.enum(["scheduled", "confirmed", "in_progress", "completed", "canceled", "no_show"]);
export const nextActionStatusSchema = z.enum(["proposed", "accepted", "scheduled", "completed", "dismissed"]);
export const syncStatusSchema = z.enum(["queued", "running", "succeeded", "retryable", "conflicted", "dead_lettered"]);
export const artifactStatusSchema = z.enum(["draft", "rep_approved", "manager_reviewed", "superseded"]);
export const calendarProviderSchema = z.enum(["google", "outlook"]);
export const integrationProviderSchema = z.enum(["google", "outlook", "csv", "reference_crm"]);

export const actorSchema = z.object({
  organizationId: z.string().uuid(), userId: z.string().uuid(), role: roleSchema,
  teamIds: z.array(z.string().uuid()).default([]), territoryIds: z.array(z.string().uuid()).default([]),
}).strict();

export const contactInputSchema = z.object({
  id: z.string().uuid().optional(), firstName: z.string().trim().min(1).max(80), lastName: z.string().trim().max(80).default(""),
  title: z.string().trim().max(120).optional(), email: z.string().email().optional(), phone: z.string().trim().max(40).optional(),
  isPrimary: z.boolean().default(false), externalId: z.string().max(200).optional(),
}).strict();

export const accountInputSchema = z.object({
  id: z.string().uuid().optional(), name: z.string().trim().min(1).max(160), accountType: z.string().trim().max(100).optional(),
  address: z.string().trim().max(500).optional(), territoryId: z.string().uuid().optional(), ownerUserId: z.string().uuid(),
  externalId: z.string().max(200).optional(), contacts: z.array(contactInputSchema).max(100).default([]),
}).strict();

export const scheduleSchema = z.object({
  startsAt: z.string().datetime(), durationMinutes: z.number().int().min(5).max(480), timezone: z.string().trim().min(1).max(80),
  location: z.string().trim().max(500).optional(), recurrenceRule: z.string().trim().max(500).optional(),
  remindersMinutes: z.array(z.number().int().min(0).max(40_320)).max(5).default([30]), calendarProvider: calendarProviderSchema.optional(),
}).strict();

export const startCycleInputSchema = z.object({
  account: accountInputSchema, contactIds: z.array(z.string().uuid()).max(25).default([]), purpose: z.string().trim().min(1).max(1_000),
  diseaseFocus: z.string().trim().max(160).optional(), schedule: scheduleSchema,
}).strict();

export const completeCallInputSchema = z.object({
  callId: z.string().uuid(), expectedVersion: z.number().int().positive(), outcome: z.enum(["advanced", "follow_up", "not_interested", "reschedule", "no_show", "canceled"]),
  notes: z.string().trim().max(10_000).optional(), summary: z.string().trim().max(10_000).optional(), transcript: z.string().max(100_000).optional(),
  consentConfirmed: z.boolean(), commitments: z.array(z.string().trim().min(1).max(500)).max(25).default([]),
  referralSignals: z.array(z.string().trim().min(1).max(500)).max(25).default([]),
}).strict().superRefine((value, context) => {
  if (value.transcript && !value.consentConfirmed) context.addIssue({ code: "custom", path: ["consentConfirmed"], message: "Consent is required before transcript analysis" });
});

export const nextCallInputSchema = z.object({
  cycleId: z.string().uuid(), expectedVersion: z.number().int().positive(), nextActionId: z.string().uuid().optional(), schedule: scheduleSchema,
  purpose: z.string().trim().min(1).max(1_000), contactIds: z.array(z.string().uuid()).max(25).default([]),
}).strict();

export interface VersionedEntity { id: string; organizationId: string; createdAt: string; updatedAt: string; version: number; deletedAt?: string; }
export interface Account extends VersionedEntity { name: string; accountType?: string; address?: string; territoryId?: string; ownerUserId: string; externalId?: string; }
export interface Contact extends VersionedEntity { accountId: string; firstName: string; lastName: string; title?: string; email?: string; phone?: string; isPrimary: boolean; externalId?: string; }
export interface AccountSnapshot { account: Account; contacts: Contact[]; recentActivities: Activity[]; capturedAt: string; sourceIds: string[]; }
export interface SalesCycle extends VersionedEntity { accountId: string; ownerUserId: string; purpose: string; diseaseFocus?: string; status: "active" | "completed" | "archived"; }
export interface CallPlan extends VersionedEntity { cycleId: string; callId: string; status: z.infer<typeof planStatusSchema>; content?: unknown; artifact?: AiArtifact; }
export interface SalesCall extends VersionedEntity { cycleId: string; accountId: string; ownerUserId: string; contactIds: string[]; purpose: string; schedule: z.infer<typeof scheduleSchema>; status: z.infer<typeof callStatusSchema>; calendarEventId?: string; }
export interface CallOutcome extends VersionedEntity { callId: string; outcome: z.infer<typeof completeCallInputSchema>["outcome"]; notes?: string; summary?: string; encryptedTranscript?: string; consentConfirmed: boolean; commitments: string[]; referralSignals: string[]; }
export interface Activity extends VersionedEntity { accountId: string; cycleId?: string; type: string; summary: string; occurredAt: string; actorUserId: string; }
export interface AiArtifact { status: z.infer<typeof artifactStatusSchema>; toolId: string; promptVersion: string; schemaVersion: string; model?: string; responseId?: string; contextCapturedAt: string; sources: string[]; warnings: string[]; usage?: { inputTokens?: number; outputTokens?: number; totalTokens?: number }; output: unknown; }
export interface CoachingSession extends VersionedEntity { callId: string; status: z.infer<typeof artifactStatusSchema>; performance?: AiArtifact; coaching?: AiArtifact; approvedBy?: string; approvedAt?: string; }
export interface NextAction extends VersionedEntity { cycleId: string; cycleVersion: number; callId: string; type: "task" | "email" | "next_call"; status: z.infer<typeof nextActionStatusSchema>; title: string; dueAt?: string; sourceCoachingId?: string; }
export interface EmailDraft extends VersionedEntity { cycleId: string; callId: string; nextActionId: string; status: z.infer<typeof artifactStatusSchema>; toContactIds: string[]; subject?: string; body?: string; artifact: AiArtifact; simulatedAbResult: true; }
export interface RoleplaySession extends VersionedEntity {cycleId:string;planId:string;ownerUserId:string;scenario:unknown;messages:Array<{role:"learner"|"prospect";content:string}>;turn:number;latestCoaching?:unknown;complete:boolean;}
export interface ImportJob extends VersionedEntity{actorUserId:string;status:"committed"|"rolled_back";insertedAccountIds:string[];imported:number;merged:number;rejected:number;rollbackTokenHash:string;rollbackExpiresAt:string;}
export interface CalendarEvent extends VersionedEntity { callId: string; provider?: z.infer<typeof calendarProviderSchema>; externalId?: string; etag?: string; syncRevision: number; contentHash?: string; deletedExternallyAt?: string; }
export interface SyncJob extends VersionedEntity { kind: "calendar" | "crm"; aggregateId: string; status: z.infer<typeof syncStatusSchema>; attempts: number; availableAt: string; idempotencyKey: string; errorCode?: string; }
export interface SyncCursor extends VersionedEntity { provider: string; connectionId: string; cursor?: string; lastPulledAt?: string; lastErrorCode?: string; }
export interface SyncConflict extends VersionedEntity {
  kind: "calendar" | "crm";
  provider: string;
  aggregateId?: string;
  externalId: string;
  status: "pending" | "keep_local" | "accept_external" | "merged" | "dismissed";
  reason: "external_changed" | "external_deleted" | "unlinked_external" | "version_mismatch";
  localVersion?: number;
  externalVersion?: string;
  detectedAt: string;
  localPayload?: Record<string, unknown>;
  externalPayload?: Record<string, unknown>;
}
export interface DomainEvent { id: string; organizationId: string; type: string; aggregateId: string; occurredAt: string; payload: Record<string, unknown>; publishedAt?: string; }
export interface AuditEvent { id: string; organizationId: string; actorUserId: string; action: string; aggregateId?: string; occurredAt: string; metadata: Record<string, unknown>; }

export type Actor = z.infer<typeof actorSchema>;
export type StartCycleInput = z.infer<typeof startCycleInputSchema>;
export type CompleteCallInput = z.infer<typeof completeCallInputSchema>;
export type NextCallInput = z.infer<typeof nextCallInputSchema>;
