import { createHash,randomUUID } from "node:crypto";
import { parse } from "csv-parse/sync";
import type { Actor } from "./schema.js";
import type { CrmAdapter, CrmRecord, ImportAdapter, ImportPreview, WorkflowStorage } from "./ports.js";
import { csvSafe, WorkflowError } from "./security.js";

export class CsvAccountImportAdapter implements ImportAdapter {
  constructor(private readonly storage: WorkflowStorage, private readonly maxBytes = 5_000_000, private readonly maxRows = 25_000) {}
  async preview(content: string): Promise<ImportPreview> { if (Buffer.byteLength(content) > this.maxBytes) throw new WorkflowError("PAYLOAD_TOO_LARGE", 413, "CSV file is too large"); const rows = parse(content.replace(/^\uFEFF/, ""), { columns: true, skip_empty_lines: true, relax_column_count: false, trim: true, bom: true, to: this.maxRows + 1 }) as Record<string, string>[]; if (rows.length > this.maxRows) throw new WorkflowError("TOO_MANY_ROWS", 413, "CSV row limit exceeded"); const headers = rows[0] ? Object.keys(rows[0]) : []; const formulaCells: Array<{ row: number; column: string }> = []; rows.forEach((row, index) => Object.entries(row).forEach(([column, value]) => { if (/^[=+\-@\t\r]/.test(value)) formulaCells.push({ row: index + 2, column }); })); return { headers, rows, warnings: rows.length ? [] : ["The CSV contains no data rows"], formulaCells }; }
  private securePreview(preview:ImportPreview):ImportPreview{if(!preview||!Array.isArray(preview.headers)||!Array.isArray(preview.rows))throw new WorkflowError("INVALID_IMPORT",400,"Import preview is malformed");if(preview.rows.length>this.maxRows||Buffer.byteLength(JSON.stringify(preview))>this.maxBytes*2)throw new WorkflowError("PAYLOAD_TOO_LARGE",413,"Import preview exceeds configured limits");const headers=preview.headers.map(String);if(new Set(headers).size!==headers.length)throw new WorkflowError("INVALID_IMPORT",400,"Import preview has duplicate headers");const formulaCells:Array<{row:number;column:string}>=[];const rows=preview.rows.map((row,index)=>{if(!row||typeof row!=="object"||Array.isArray(row))throw new WorkflowError("INVALID_IMPORT",400,`Row ${index+2} is malformed`);const clean:Record<string,string>={};for(const header of headers){const value=(row as Record<string,unknown>)[header];if(typeof value!=="string")throw new WorkflowError("INVALID_IMPORT",400,`Row ${index+2} contains a non-text value`);if(value.length>2_000)throw new WorkflowError("INVALID_IMPORT",400,`Row ${index+2} contains an overlong value`);clean[header]=value;if(/^[=+\-@\t\r]/.test(value))formulaCells.push({row:index+2,column:header})}return clean});return{headers,rows,warnings:Array.isArray(preview.warnings)?preview.warnings.map(String):[],formulaCells}}
  async validate(preview: ImportPreview, mapping: Record<string, string>) { const safe=this.securePreview(preview);const errors: string[] = [];const allowed=new Set(["accountName","accountType","address","externalId"]); if (!Object.values(mapping).includes("accountName")) errors.push("Map one column to accountName"); for (const [source,target] of Object.entries(mapping)){if (!safe.headers.includes(source)) errors.push(`Mapped column does not exist: ${source}`);if(!allowed.has(target))errors.push(`Unsupported destination field: ${target}`)}if(new Set(Object.values(mapping)).size!==Object.values(mapping).length)errors.push("Each destination field can be mapped only once"); if (safe.formulaCells.length) errors.push(`${safe.formulaCells.length} formula-like cells require review`); return { valid: errors.length === 0, errors }; }
  async commit(preview: ImportPreview, mapping: Record<string, string>, actor: Actor, dryRun = false) { const safe=this.securePreview(preview);const validated = await this.validate(safe, mapping); if (!validated.valid) throw new WorkflowError("INVALID_IMPORT", 400, validated.errors.join("; ")); let imported = 0, merged = 0, rejected = 0;const rollbackToken=randomUUID();const rollbackTokenHash=createHash("sha256").update(rollbackToken).digest("hex"); if (!dryRun) await this.storage.transact(actor.organizationId, async (tx) => {const insertedAccountIds:string[]=[]; for (const row of safe.rows) { const mapped = Object.fromEntries(Object.entries(mapping).map(([source, target]) => [target, row[source]?.trim()])); const name = String(mapped.accountName ?? ""); if (!name||name.length>300) { rejected++; continue; } const existing = (await tx.list("account", (item) => item.name.toLocaleLowerCase() === name.toLocaleLowerCase()))[0]; if (existing) { merged++; continue; } const now = new Date().toISOString();const id=randomUUID(); await tx.insert("account", { id, organizationId: actor.organizationId, createdAt: now, updatedAt: now, version: 1, name, accountType: mapped.accountType ? String(mapped.accountType) : undefined, address: mapped.address ? String(mapped.address) : undefined, externalId: mapped.externalId ? String(mapped.externalId) : undefined, ownerUserId: actor.userId });insertedAccountIds.push(id); imported++; }const now=new Date().toISOString();await tx.insert("importJob",{id:randomUUID(),organizationId:actor.organizationId,createdAt:now,updatedAt:now,version:1,actorUserId:actor.userId,status:"committed",insertedAccountIds,imported,merged,rejected,rollbackTokenHash,rollbackExpiresAt:new Date(Date.now()+24*60*60_000).toISOString()}); await tx.appendAudit({ id: randomUUID(), organizationId: actor.organizationId, actorUserId: actor.userId, action: "csv.import.committed", occurredAt: now, metadata: { imported, merged, rejected } }); }); return { imported: dryRun ? safe.rows.length : imported, merged, rejected, rollbackToken: dryRun ? undefined : rollbackToken }; }
  async rollback(rollbackToken:string,actor:Actor){const tokenHash=createHash("sha256").update(rollbackToken).digest("hex");return this.storage.transact(actor.organizationId,async(tx)=>{const job=(await tx.list("importJob",item=>item.rollbackTokenHash===tokenHash))[0];if(!job||job.actorUserId!==actor.userId)throw new WorkflowError("ROLLBACK_NOT_FOUND",404,"Import rollback token was not found");if(job.status!=="committed")throw new WorkflowError("ALREADY_ROLLED_BACK",409,"Import was already rolled back");if(job.rollbackExpiresAt<=new Date().toISOString())throw new WorkflowError("ROLLBACK_EXPIRED",410,"Import rollback window expired");let rolledBack=0;for(const id of job.insertedAccountIds){const account=await tx.get("account",id);if(account&&!account.deletedAt){await tx.update("account",{...account,deletedAt:new Date().toISOString(),updatedAt:new Date().toISOString()},account.version);rolledBack++}}await tx.update("importJob",{...job,status:"rolled_back",updatedAt:new Date().toISOString()},job.version);await tx.appendAudit({id:randomUUID(),organizationId:actor.organizationId,actorUserId:actor.userId,action:"csv.import.rolled_back",aggregateId:job.id,occurredAt:new Date().toISOString(),metadata:{rolledBack}});return{rolledBack}})}
  async exportErrors(errors: string[]) { return ["error", ...errors.map((item) => `"${csvSafe(item).replaceAll('"', '""')}"`)].join("\r\n"); }
}

export class ReferenceCrmAdapter implements CrmAdapter {
  private readonly records = new Map<string, CrmRecord>(); private readonly seenKeys = new Set<string>();
  async testConnection() { return { ok: true, message: "Reference CRM is available" }; }
  async getCapabilities() { return { pull: true, push: true, webhooks: false, objects: ["account", "contact", "activity"] }; }
  async pullChanges(cursor?: string) { const records = [...this.records.values()].filter((record) => !cursor || (record.version ?? "") > cursor); return { records: structuredClone(records), cursor: new Date().toISOString() }; }
  async pushChanges(records: CrmRecord[], idempotencyKey: string) { if (this.seenKeys.has(idempotencyKey)) return { accepted: records.map((item) => item.externalId), conflicts: [] }; this.seenKeys.add(idempotencyKey); const accepted: string[] = [], conflicts: Array<{ externalId: string; reason: string }> = []; for (const record of records) { const current = this.records.get(record.externalId); if (current?.version && record.version && current.version !== record.version) { conflicts.push({ externalId: record.externalId, reason: "version_mismatch" }); continue; } this.records.set(record.externalId, { ...structuredClone(record), version: new Date().toISOString() }); accepted.push(record.externalId); } return { accepted, conflicts }; }
  async resolveExternalRecord(_object: CrmRecord["object"], externalId: string) { const record = this.records.get(externalId); return record ? structuredClone(record) : undefined; }
}

export function applyWebsiteWins(local: Record<string, unknown>, external: Record<string, unknown>, fieldMapping: Record<string, string>): Record<string, unknown> { const result = { ...external }; for (const [localField, externalField] of Object.entries(fieldMapping)) if (localField in local) result[externalField] = local[localField]; return result; }
