import { createCipheriv, createDecipheriv, createHash, randomBytes } from "node:crypto";
import type { Actor } from "./schema.js";
import type { AuthorizationAdapter, EncryptionAdapter } from "./ports.js";

export class WorkflowError extends Error {
  constructor(public readonly code: string, public readonly status: number, message: string, public readonly details?: Record<string, unknown>) { super(message); }
}

export class DefaultAuthorization implements AuthorizationAdapter {
  assert(actor: Actor, action: string, resource?: { organizationId: string; ownerUserId?: string }): void {
    if (resource?.organizationId && resource.organizationId !== actor.organizationId) throw new WorkflowError("FORBIDDEN", 403, "Resource is outside your organization");
    const integrationAction = action.startsWith("integration:");
    if (integrationAction && actor.role !== "integration_admin") throw new WorkflowError("FORBIDDEN", 403, "Integration administrator access is required");
    if (action.startsWith("manager:") && actor.role !== "manager") throw new WorkflowError("FORBIDDEN", 403, "Manager access is required");
    if (resource?.ownerUserId && actor.role === "rep" && resource.ownerUserId !== actor.userId) throw new WorkflowError("FORBIDDEN", 403, "You do not own this workflow");
  }
}

export class AesGcmEncryption implements EncryptionAdapter {
  private readonly key: Buffer;
  constructor(key: Buffer | string) {
    const raw = typeof key === "string" ? Buffer.from(key, "base64") : key;
    if (raw.length !== 32) throw new Error("Encryption key must be 32 bytes");
    this.key = raw;
  }
  async encrypt(plaintext: string, purpose: string): Promise<string> {
    const iv = randomBytes(12); const cipher = createCipheriv("aes-256-gcm", this.key, iv); cipher.setAAD(Buffer.from(purpose));
    const data = Buffer.concat([cipher.update(plaintext, "utf8"), cipher.final()]);
    return ["v1", iv.toString("base64url"), cipher.getAuthTag().toString("base64url"), data.toString("base64url")].join(".");
  }
  async decrypt(ciphertext: string, purpose: string): Promise<string> {
    const [version, iv, tag, data] = ciphertext.split(".");
    if (version !== "v1" || !iv || !tag || !data) throw new WorkflowError("INVALID_CIPHERTEXT", 400, "Encrypted value is invalid");
    const decipher = createDecipheriv("aes-256-gcm", this.key, Buffer.from(iv, "base64url"));
    decipher.setAAD(Buffer.from(purpose)); decipher.setAuthTag(Buffer.from(tag, "base64url"));
    return Buffer.concat([decipher.update(Buffer.from(data, "base64url")), decipher.final()]).toString("utf8");
  }
}

export function sanitizeExternalText(value: string, max = 10_000): string {
  return value.replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F]/g, " ").replace(/(?:system|assistant|developer)\s*:/gi, "[external label removed]:").slice(0, max).trim();
}
export function safeLogMetadata(value: { organizationId?: string; userId?: string; requestId?: string; operation: string; durationMs?: number; errorCode?: string }): Record<string, unknown> {
  return { operation: value.operation, requestId: value.requestId, durationMs: value.durationMs, errorCode: value.errorCode,
    organizationHash: value.organizationId ? createHash("sha256").update(value.organizationId).digest("hex").slice(0, 16) : undefined,
    userHash: value.userId ? createHash("sha256").update(value.userId).digest("hex").slice(0, 16) : undefined };
}
export function csvSafe(value: string): string { return /^[=+\-@\t\r]/.test(value) ? `'${value}` : value; }
